def _write_bulk_job_artifacts(job_file, log_file, batch):
    for operation, value in batch:
        if operation == "status":
            _write_carto_job_payload(job_file, value)
        elif operation == "log":
            _append_carto_job_log(log_file, value)
        elif operation == "result-log":
            _append_carto_job_log(log_file, _bulk_result_log_text(*value))
        else:
            raise ValueError(f"Unknown bulk artifact operation: {operation}")

