async def _carto_task_terminal_payload(spec: CartoJobSpec, control: CartoJobControl, outcome: Mapping[str, Any]) -> dict[str, Any]:
    """Retain saved work and exact local CPU attribution at one exit.

    A caught mapper exception, including a coded file error, is local only when
    file/phase/type/message provenance survives in that file's failed row.
    Nested bulk job JSON uses its same result_summary.files provenance. Inline
    phase8 failures may carry it in phase8.files for a primary canonical file;
    that failed refresh never changes a committed publication into a failed row.
    Switched jobs recover only their registered writer's summary and attribute
    CPU failures through its contribution summaries, never a rows list. Only a
    job without a writer reads its saved record; a read error is failure data.
    A single-FILE return is appended here, before normalization, so internal
    FILE callers still receive their complete working result. The runner's
    owned outcome relinquishes that row after its append, not into the proof.
    Unattributed and named run-wide failures stay fatal; no exception/control
    crosses into the data worker.
    """
    original_phase = control.phase
    from .carto_job_record import record_for
    writer = record_for(spec.job_file, create=False)
    result = outcome.get("result")
    if (writer is not None and writer._is_file and isinstance(result, Mapping)
            and "file" in result and not result.get("_carto_writer_summary")):
        from .client.api_client_nexus import _write_carto_file_artifact
        row = outcome.pop("result") if isinstance(outcome, dict) else result
        result = None
        try:
            result = await run_carto_cpu("terminal-file-row", _write_carto_file_artifact, "file-row", {
                "path": str(spec.job_file), "row": row,
            })
        finally:
            row = None
    saved_read_error = None
    if not isinstance(result, Mapping):
        if writer is not None:
            result = writer.summary()
        else:
            try:
                saved = await run_carto_cpu("terminal-saved-result", _read_carto_job_payload, str(spec.job_file), strict=True)
                result = saved.get("result_summary") if isinstance(saved, Mapping) else None
            except Exception as read_error:
                saved_read_error = read_error
    exception = outcome.get("exception") or saved_read_error
    if control.cpu_failure is not None:
        phase, cpu_exception = control.cpu_failure
        from .carto_job_governance import GovernanceError
        identity = {"phase": phase, "exception_type": type(cpu_exception).__name__, "message": str(cpu_exception)}
        summary = (result.get("result_summary") or result) if isinstance(result, Mapping) else {}
        if writer is not None:
            attributed = writer.accumulator.local_cpu_failure(identity)
        else:
            primary_rows = summary.get("files") or []
            primary_files = {row["file"] for row in primary_rows if row.get("file")}
            phase8_rows = [row for row in (summary.get("phase8") or {}).get("files") or []
                           if row.get("file") in primary_files]
            attributed = any(row.get("status") == "failed" and row.get("error")
                and row.get("local_cpu_failure") == {**identity, "file": row.get("file")}
                for row in [*primary_rows, *phase8_rows])
        local = (isinstance(cpu_exception, Exception) and not isinstance(cpu_exception, (
                     GovernanceError, MutationRegionError, MutationSerializationConflictError, MutationSerializationTimeoutError))
                 and not hasattr(cpu_exception, "refusal_extra") and getattr(cpu_exception, "code", None) not in {
                     "ACCOUNT_WRITE_BLOCKED", "WRITE_GOVERNOR_UNAVAILABLE", "WRITE_GOVERNOR_DEFERRED",
                     "WRITE_SLOT_BUSY_TIMEOUT", "AUTH_ERROR", "RATE_LIMIT_ERROR"}
                 and phase in {"file:source", "file:plan", "folder:new-source", "folder:new-retention"}
                 and isinstance(result, Mapping) and attributed)
        if not local:
            exception = exception or cpu_exception
    else:
        phase = original_phase
    exception_data = None
    if exception is not None:
        kind = "scheduling_failed" if outcome.get("scheduling_failed") else "carto_job_exception"
        typed_extra = {}
        coherence_prefix = hasattr(exception, "refusal_extra")
        if coherence_prefix:
            kind, typed_extra = getattr(exception, "code", "coherence_barrier_active"), exception.refusal_extra()
        elif isinstance(exception, (MutationRegionError, MutationSerializationConflictError, MutationSerializationTimeoutError)):
            kind, typed_extra = exception.code, _mutation_refusal_extra(exception)
        elif isinstance(exception, AdmissionRefusal):
            kind, typed_extra = exception.kind, exception.details
        elif getattr(exception, "code", None) in {"ACCOUNT_WRITE_BLOCKED", "WRITE_GOVERNOR_DEFERRED"}:
            kind, typed_extra = exception.code, dict(exception.details)
        exception_data = {"type": type(exception).__name__, "text": str(exception), "kind": kind,
                          "extra": typed_extra, "coherence_prefix": coherence_prefix}
    metadata = {"job_id": spec.job_id, "job_type": spec.job_type, "mode": spec.mode,
                "root_uuid": spec.root_uuid, "claim_id": spec.claim_id, "pid": os.getpid(), "phase": phase,
                "may_have_workflowy_effects": control.may_have_workflowy_effects,
                "stopped": control.user_observed or control.restart_state["observed"],
                "restart_observed": control.restart_state["observed"], "exception": exception_data,
                "scheduling_failed": bool(outcome.get("scheduling_failed")), "updated_at": datetime.utcnow().isoformat()}
    if writer is not None:
        metadata["writer_job_file"] = str(spec.job_file)
    outcome_data = {key: outcome.get(key) for key in ("status", "error", "result_summary")}
    return await run_carto_cpu("terminal-normalize", _carto_terminal_payload_data, metadata, result, outcome_data)

